import {input as contextInput,material} from '../context/builders.mjs';
import {buildContextAssessment} from '../../../lib/credit-engine/context/engine.ts';
export {material};
export function baseline(){const x=contextInput();return {riskAssessment:x.riskAssessment,contextAssessment:buildContextAssessment(x),asOfDate:x.asOfDate};}
export function finding(x,{id='synthetic-risk',code='SYN-FIN-RISK',domain='FINANCIAL',severity='HIGH',scope='CREDIT_RISK',subjectKey,reasonCodes=['SYNTHETIC_RISK']}={}){const f=x.riskAssessment.facts.find(f=>f.semanticCode===(domain==='LEGAL'?'LEGAL_LIFECYCLE':domain==='CASH_FLOW'?'BANK_OPERATING_TREND':'FIN_EQUITY'));const r={findingId:id,code,ruleVersion:'PRESCORE-RISK-RULES-1.0.0-PRE-CALIBRATION',domain,scope,severity,decisionImpact:scope==='GLOBAL_STOP'?'BLOCKING':scope==='INFORMATION'?'NON_BLOCKING':'REVIEW',calibrationClass:'PRE_CREDIT_LAB',evidenceConfidence:'HIGH',requiresDataReview:scope==='DATA_REVIEW',actualValue:1,unit:f.unit,reasonCodes,factIds:[f.factId],evidence:structuredClone(f.evidence),calculationBasis:'Independently authored synthetic canonical finding for Index policy validation',warnings:[],origin:'REPORTED',...(subjectKey?{subjectKey}:{})};x.riskAssessment.findings.push(r);if(scope==='GLOBAL_STOP')x.riskAssessment.summary.globalStopStatus='TRIGGERED';return r;}
export function relation(x,target,{id='synthetic-context',effect='MITIGATES',confidence='HIGH',sourceClass='CANONICAL_OBSERVED'}={}){const f=structuredClone(x.contextAssessment.facts.find(f=>f.semanticCode==='FIN_EQUITY'));f.factId=`${id}:fact`;f.sourceClass=sourceClass;f.confidence=confidence;f.sourceIds=[`${id}:source`];f.sourceRiskFactIds=[];f.evidence=f.evidence.map(e=>({...e,evidenceId:`${id}:evidence`,sourceId:`${id}:source`,sourceClass,confidence}));x.contextAssessment.facts.push(f);const r={relationId:id,code:`SYN-CONTEXT-${id}`,ruleVersion:'PRESCORE-CONTEXT-RULES-1.0.0-PRE-INDEX',domain:'WORKING_CAPITAL',effect,targetRiskFindingIds:[target.findingId],targetRiskCodes:[target.code],contextFactIds:[f.factId],evidenceConfidence:confidence,reasonCodes:['SYNTHETIC_CONTEXT'],calculationBasis:'Independent canonical context fixture; no current Index output used as expected',warnings:[]};x.contextAssessment.relations.push(r);return r;}
export function removeCore(x,codes){for(const f of x.riskAssessment.facts)if(codes.includes(f.semanticCode)){f.status='UNKNOWN';f.value=null;}for(const f of x.contextAssessment.facts)if(codes.includes(f.semanticCode)){f.status='UNKNOWN';f.value=null;}}
export function rawProfile(m=material()){const x=contextInput(m);return {riskAssessment:x.riskAssessment,contextAssessment:buildContextAssessment(x),asOfDate:x.asOfDate};}
